/* ===================== Outils d'affichage ===================== */
function ringSvg(p,size=84,color,stroke=9){const r=(size-stroke-3)/2,c=2*Math.PI*r;return `<svg class="ring" width="${size}" height="${size}"><circle class="track" cx="${size/2}" cy="${size/2}" r="${r}" style="stroke-width:${stroke}"/><circle class="val" cx="${size/2}" cy="${size/2}" r="${r}" stroke-dasharray="${c}" stroke-dashoffset="${c}" data-off="${c*(1-p)}" style="stroke-width:${stroke};${color?`stroke:${color}`:''}"/></svg>`}
function animateRings(){requestAnimationFrame(()=>requestAnimationFrame(()=>$$('.ring .val').forEach(e=>e.style.strokeDashoffset=e.dataset.off)))}
function countUp(){$$('[data-count]').forEach(el=>{const to=+el.dataset.count,suf=el.dataset.suf||'';const t0=performance.now();const step=t=>{const k=Math.min(1,(t-t0)/700),e=1-Math.pow(1-k,3);el.textContent=Math.round(to*e)+suf;if(k<1)requestAnimationFrame(step)};requestAnimationFrame(step)})}
const folderSvg=(c,s=46)=>`<svg width="${s}" height="${Math.round(s*0.82)}" viewBox="0 0 56 46" aria-hidden="true"><path d="M2 8a4 4 0 0 1 4-4h14l5 5h25a4 4 0 0 1 4 4v3H2z" fill="${c}" opacity=".7"/><rect x="2" y="12" width="52" height="32" rx="5" fill="${c}"/><rect x="2" y="12" width="52" height="7" rx="3" fill="#fff" opacity=".2"/></svg>`;
function folderHub(compact){return `<div class="folders ${compact?'compact':''}">
 <a class="folder-tile readme" href="${DRIVE.readme}" target="_blank" rel="noopener"><span class="fpic">${ui('spark',24)}</span><span><b>Le projet en 1 page</b><small>À lire en premier</small></span></a>
 ${DRIVE.folders.map(([n,l,id,c,d])=>`<a class="folder-tile" href="${folderUrl(id)}" target="_blank" rel="noopener">${folderSvg(c)}<span><b>${n} · ${esc(l)}</b><small>${esc(d)}</small></span></a>`).join('')}</div>`}
const tabsHtml=(list,cur,fn)=>`<div class="seg big">${list.map(([k,l,i])=>`<button class="${cur===k?'on':''}" onclick="${fn}('${k}')">${i?ui(i,16):''} ${l}</button>`).join('')}</div>`;
const pageHead=(title,sub,actions='')=>`<div class="page-head"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions?`<div class="row">${actions}</div>`:''}</div>`;

/* ===================== ACCUEIL ===================== */
function personStats(m){const T=arr('tasks').filter(t=>t.owner===m.id);const done=T.filter(t=>isDone(t.status)).length;const fr=D.fr.get(slug(m.name))?.items||{};const comp=Object.values(fr).filter(x=>x.status==='validated').length;return{T,done,open:T.length-done,comp}}
VIEWS.accueil=function(){
 const T=arr('tasks'),done=T.filter(t=>isDone(t.status)).length,pct=T.length?done/T.length:0;
 const mine=T.filter(t=>t.owner===ME.id&&!isDone(t.status)).sort((a,b)=>(a.due||'9').localeCompare(b.due||'9'));
 const nu=unread();const feed=arr('activity').sort((a,b)=>b.ts-a.ts).slice(0,6);const seen=ls.get(seenKey(),0);
 const alerts=D.meta.get('alerts')?.list||[];
 $('#view').innerHTML=`
 <section class="hero"><div class="hero-bg"></div><div class="hero-txt">
  <div class="eyebrow light">${fmtDL(todayISO())}</div><h1>Bonjour ${esc(ME.name)}</h1>
  <p>${mine.length?`Tu as <b>${mine.length} tâche${mine.length>1?'s':''}</b> à faire.`:'Aucune tâche à ton nom pour l\'instant.'} ${nu.length?`<b>${nu.length} changement${nu.length>1?'s':''}</b> depuis ta dernière visite.`:'Tu es à jour.'}</p>
  <div class="row" style="margin-top:18px"><a class="btn glass" href="#taches">${ui('tasks',16)} Mes tâches</a><a class="btn glass" href="#infra">${ui('topo',16)} Infrastructure</a><a class="btn glass" href="#documents">${ui('docs',16)} Documents</a></div></div>
  <div class="hero-ring">${ringSvg(pct,132,'#ffffff',10)}<div class="hero-ring-txt"><b data-count="${Math.round(pct*100)}" data-suf="%">0%</b><span>des tâches terminées</span></div></div></section>

 <section class="block"><div class="block-head"><h2>Où trouver quoi</h2><span class="muted small">Les dossiers du Drive, dans l'ordre du projet</span></div>${folderHub()}</section>

 <section class="block"><div class="block-head"><h2>L'équipe</h2><a class="small" href="#equipe">Modifier</a></div>
 <div class="grid g-4 stagger">${members().map((m,i)=>{const s=personStats(m);const p=s.T.length?s.done/s.T.length:0;return `<a class="card hover person" style="--i:${i};--c:${m.color}" href="#taches" onclick="TU.owner='${m.id}';TU.tab='tableau'">
  <div class="row between" style="flex-wrap:nowrap"><div class="row" style="flex-wrap:nowrap;min-width:0">${avatar(m.name,m.color,'lg')}<div style="min-width:0"><b>${esc(m.name)}${m.id===ME.id?' <span class="tiny muted">(moi)</span>':''}</b><div class="tiny muted">${esc(m.role)}</div></div></div><div class="mini-ring">${ringSvg(p,52,m.color,6)}<span>${Math.round(p*100)}%</span></div></div>
  <div class="stats"><div><b>${s.open}</b><span>à faire</span></div><div><b>${s.done}</b><span>terminées</span></div><div><b>${s.comp}<small>/30</small></b><span>compétences</span></div></div></a>`}).join('')}</div></section>

 <div class="grid g-2">
  <section class="card"><div class="card-head"><h2>Mes prochaines tâches</h2><button class="btn sm primary" onclick="editTask()">${ui('plus',14)} Tâche</button></div>
   ${mine.length?`<ul class="list">${mine.slice(0,6).map(t=>`<li><span class="row" style="flex-wrap:nowrap;gap:10px;min-width:0"><span class="dot" style="background:${TASK_ST.find(s=>s[0]===t.status)?.[2]}"></span><a href="javascript:void 0" onclick="editTask('${t.id}')">${esc(t.title)}</a></span><span class="row" style="gap:6px;flex-wrap:nowrap">${t.due?`<span class="chip ${t.due<todayISO()?'bad':''}">${fmtD(t.due)}</span>`:''}<button class="btn sm ghost" title="Marquer comme terminée" onclick="setTaskStatus('${t.id}','done')">✓</button></span></li>`).join('')}</ul>`:`<div class="empty small">Rien à ton nom. Crée une tâche ou prends-en une dans le tableau.</div>`}</section>
  <section class="card"><div class="card-head"><h2>Ce que le groupe a fait</h2><button class="btn sm ghost" onclick="toggleBell()">Tout voir</button></div>
   <ul class="list feed">${feed.map(a=>`<li class="${a.ts>seen&&a.who!==ME.name?'unread':''}">${avatar(a.who,a.color||colorOf(a.who))}<span class="t small"><b>${esc(a.who)}</b> ${esc(a.verb)} ${a.route?`<a href="#${a.route}">${esc(a.label)}</a>`:esc(a.label)}</span><span class="tiny muted">${ago(a.ts)}</span></li>`).join('')||'<li class="muted small">Les modifications de chacun apparaîtront ici.</li>'}</ul></section>
 </div>
 <section class="card" style="margin-top:18px"><div class="card-head"><div><h2>Questions à poser aux profs</h2><span class="muted small">Infos manquantes ou contradictions trouvées dans les consignes</span></div><button class="btn sm ghost" onclick="addAlert()">${ui('plus',14)} Ajouter</button></div>${alerts.map((a,i)=>`<label class="alert ${a.done?'done':''}"><input type="checkbox" ${a.done?'checked':''} onchange="toggleAlert(${i},this.checked)"><span class="small">${esc(a.text)}</span></label>`).join('')||'<p class="muted small">Aucune question.</p>'}</section>`;
 animateRings();countUp();
};
async function toggleAlert(i,v){const d=clone(D.meta.get('alerts'))||{list:[]};d.list[i].done=v;await put('meta','alerts',{list:d.list},v?['a coché une question pour les profs',trunc(d.list[i].text,50),'accueil']:null)}
async function addAlert(){const t=await promptBox('Question à poser aux profs');if(!t)return;const d=clone(D.meta.get('alerts'))||{list:[]};d.list.push({text:t,done:false});await put('meta','alerts',{list:d.list},['a ajouté une question pour les profs',trunc(t,50),'accueil'])}

/* ===================== TÂCHES ET PLANNING ===================== */
let TU={tab:'tableau',owner:''};
const setTU=k=>{TU.tab=k;renderView()};
const weekStart=d=>{const x=new Date(d+'T12:00');x.setDate(x.getDate()-((x.getDay()+6)%7));return x.toISOString().slice(0,10)};
const addDays=(d,n)=>{const x=new Date(d+'T12:00');x.setDate(x.getDate()+n);return x.toISOString().slice(0,10)};
const WEEKS=()=>{const w0=weekStart(todayISO());return [...Array(6)].map((_,i)=>addDays(w0,i*7))};
const weekLabel=w=>{const t=weekStart(todayISO());if(w===t)return 'Cette semaine';if(w===addDays(t,7))return 'Semaine prochaine';return 'Semaine du '+fmtD(w)};
const blockedBy=t=>(t.deps||[]).map(d=>D.tasks.get(d)).filter(x=>x&&!isDone(x.status));
const filtTasks=()=>arr('tasks').filter(t=>!TU.owner||t.owner===TU.owner).sort((a,b)=>(a.code||'').localeCompare(b.code||'',undefined,{numeric:true}));
VIEWS.taches=function(){
 const people=[{id:'',name:'Tout le monde'},...members(),member('all')];
 $('#view').innerHTML=pageHead('Tâches et planning','Crée une tâche, donne-la à quelqu\'un et place-la dans une semaine. Glisse les cartes pour changer leur statut ou leur semaine.',`<button class="btn primary" onclick="editTask()">${ui('plus',16)} Nouvelle tâche</button>`)+
 `<div class="row between" style="margin-bottom:18px">${tabsHtml([['tableau','Tableau','tasks'],['semaines','Semaines','gantt'],['agenda','Agenda','calendar']],TU.tab,'setTU')}
 <div class="people-filter">${people.map(m=>`<button class="pf ${TU.owner===m.id?'on':''}" onclick="TU.owner='${m.id}';renderView()">${m.id?avatar(m.name,m.color):`<span class="avatar" style="background:#64748b">${ui('team',13)}</span>`}<span>${esc(m.id===ME.id?'Moi':m.name)}</span></button>`).join('')}</div></div><div id="tv"></div>`;
 ({tableau:tvBoard,semaines:tvWeeks,agenda:tvAgenda})[TU.tab]();
};
function taskCard(t,withStatus){const bl=blockedBy(t);const m=member(t.owner);const st=TASK_ST.find(s=>s[0]===t.status);
 return `<div class="tcard" style="--c:${m.color}" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${t.id}');this.classList.add('dragging')" ondragend="this.classList.remove('dragging')" onclick="editTask('${t.id}')">
 <div class="t">${esc(t.title)}</div>
 <div class="meta">${avatar(m.name,m.color)}${withStatus?`<span class="chip" style="color:${st?.[2]}">${st?.[1]}</span>`:''}${t.priority==='haute'?'<span class="chip bad">Prioritaire</span>':''}${t.due?`<span class="chip ${t.due<todayISO()&&!isDone(t.status)?'bad':''}">${ui('calendar',12)} ${fmtD(t.due)}</span>`:''}${bl.length&&!isDone(t.status)?`<span class="chip warn" title="Attend : ${esc(bl.map(b=>b.title).join(', '))}">En attente</span>`:''}${(t.docs||[]).length?`<span class="chip">${ui('docs',12)} ${t.docs.length}</span>`:''}</div></div>`}
function tvBoard(){const L=filtTasks();
 $('#tv').innerHTML=!arr('tasks').length?`<div class="empty big">${ui('tasks',34)}<h3>Aucune tâche pour l'instant</h3><p>Commencez par lister ce que chacun doit faire cette semaine.</p><button class="btn primary" onclick="editTask()">Créer la première tâche</button></div>`:
 `<div class="kanban">${TASK_ST.map(([k,l,c])=>{const col=L.filter(t=>t.status===k);return `<div class="col" ondragover="event.preventDefault();this.classList.add('over')" ondragleave="this.classList.remove('over')" ondrop="dropTask(event,this,'status','${k}')"><div class="col-h"><span class="dot" style="background:${c}"></span>${l}<span class="n">${col.length}</span></div>${col.map(t=>taskCard(t)).join('')||'<div class="col-empty">Glisse une tâche ici</div>'}${k==='todo'?`<button class="add-in-col" onclick="editTask()">${ui('plus',14)} Ajouter</button>`:''}</div>`}).join('')}</div>`}
function tvWeeks(){const L=filtTasks();const W=WEEKS();const inWeek=(t,w)=>t.start&&weekStart(t.start)===w;
 const unplanned=L.filter(t=>!t.start&&!isDone(t.status));const late=L.filter(t=>t.start&&t.start<W[0]&&!isDone(t.status));const later=L.filter(t=>t.start&&t.start>addDays(W[W.length-1],6));
 const col=(key,title,sub,list,cls='')=>`<div class="col week ${cls}" ondragover="event.preventDefault();this.classList.add('over')" ondragleave="this.classList.remove('over')" ondrop="dropTask(event,this,'week','${key}')"><div class="col-h col-h2"><span>${title}</span><span class="tiny muted">${sub}</span></div>${list.map(t=>taskCard(t,true)).join('')||'<div class="col-empty">Glisse une tâche ici</div>'}</div>`;
 $('#tv').innerHTML=`<p class="hint-line">${ui('spark',14)} Glisse une tâche dans une semaine pour la planifier (du lundi au vendredi). Sa date de fin apparaît dans l'agenda.</p><div class="kanban weeks">${col('none','À planifier','pas encore de date',unplanned,'none')}${late.length?col('late','En retard','semaine passée',late,'late'):''}${W.map(w=>col(w,weekLabel(w),`${fmtD(w)} → ${fmtD(addDays(w,4))}`,L.filter(t=>inWeek(t,w)),w===W[0]?'now':'')).join('')}${later.length?col('later','Plus tard','',later):''}</div>`}
function dropTask(e,colEl,kind,val){e.preventDefault();colEl.classList.remove('over');const id=e.dataTransfer.getData('text/plain');const t=clone(D.tasks.get(id));if(!t)return;
 if(kind==='status'){if(t.status===val)return;t.status=val;put('tasks',id,t,['a passé',`« ${t.title} » en ${stL(TASK_ST,val)}`,'taches']);return}
 if(val==='late'||val==='later')return;if(val==='none'){t.start='';t.due='';put('tasks',id,t,['a retiré du planning',`« ${t.title} »`,'taches']);return}
 t.start=val;t.due=addDays(val,4);put('tasks',id,t,['a planifié',`« ${t.title} » (${weekLabel(val).toLowerCase()})`,'taches'])}
function setTaskStatus(id,st){const t=clone(D.tasks.get(id));if(!t||t.status===st)return;t.status=st;put('tasks',id,t,['a passé',`« ${t.title} » en ${stL(TASK_ST,st)}`,'taches'])}
function editTask(id){const t=id?D.tasks.get(id):null;const v=t||{status:'todo',priority:'moyenne',owner:ME.id};const W=WEEKS();const wk=v.start?weekStart(v.start):'';
 const opt=(a,cur)=>a.map(([k,l])=>`<option value="${esc(k)}" ${String(k)===String(cur??'')?'selected':''}>${esc(l)}</option>`).join('');
 const weeks=[['','Plus tard'],...W.map(w=>[w,weekLabel(w)])];if(wk&&!W.includes(wk))weeks.push([wk,'Semaine du '+fmtD(wk)]);
 const o=openModal(t?'Modifier la tâche':'Nouvelle tâche',`<form class="form" id="tf">
 <label class="field wide"><span>Quoi ?</span><input id="t_title" value="${esc(v.title||'')}" placeholder="Ex. Configurer le VLAN 20 sur le switch" required></label>
 <label class="field"><span>Qui ?</span><select id="t_owner">${opt(memberOpts().map(o=>[o.v,o.l]),v.owner)}</select></label>
 <label class="field"><span>Statut</span><select id="t_status">${opt(TASK_ST,v.status)}</select></label>
 <label class="field wide"><span>Détails (facultatif)</span><textarea id="t_desc" rows="3">${esc(v.desc||'')}</textarea></label>
 <div class="field wide plan-box"><span>${ui('gantt',14)} Mettre dans le planning</span>
  <div class="row" style="gap:8px">${weeks.map(([w,l])=>`<label class="pill-radio"><input type="radio" name="t_week" value="${w}" ${wk===w?'checked':''}><span>${esc(l)}</span></label>`).join('')}</div>
  <div class="row" style="margin-top:12px;gap:12px"><label class="field" style="flex:1;min-width:150px"><span>À finir pour le (facultatif)</span><input type="date" id="t_due" value="${esc(v.due||'')}"></label><label class="field" style="flex:1;min-width:120px"><span>Priorité</span><select id="t_prio">${opt(PRIO,v.priority)}</select></label></div>
  <label class="row small" style="margin-top:12px;flex-wrap:nowrap"><input type="checkbox" id="t_cal"> <span>${ui('calendar',14)} Ajouter aussi un créneau dans l'agenda du groupe</span></label>
  <div class="row" id="t_calbox" hidden style="margin-top:8px;gap:12px"><label class="field" style="flex:1"><span>Jour</span><input type="date" id="t_cdate" value="${esc(v.due||wk||todayISO())}"></label><label class="field" style="flex:1"><span>Heure</span><input type="time" id="t_ctime" value="14:00"></label></div></div>
 <details class="field wide adv"><summary>Relier à un document, une exigence ou une autre tâche (facultatif)</summary>
  <div class="grid g-3" style="margin-top:10px">${fieldHtml({k:'deps',label:'Attend la fin de',type:'multi',options:arr('tasks').filter(x=>!t||x.id!==t.id).map(x=>({v:x.id,l:x.title}))},v.deps)}${fieldHtml({k:'docs',label:'Documents',type:'multi',options:arr('docs').map(d=>({v:d.id,l:d.title}))},v.docs)}${fieldHtml({k:'reqs',label:'Exigences du CDC',type:'multi',options:REQS.map(r=>({v:r.id,l:`${r.id} · ${r.domain}`}))},v.reqs)}</div></details>
 <footer>${t?`<button type="button" class="btn danger" id="tdel">${ui('trash',16)} Supprimer</button>`:''}<span style="flex:1"></span><button type="button" class="btn" data-close2>Annuler</button><button class="btn primary">Enregistrer</button></footer></form>`,true);
 $('[data-close2]',o).onclick=closeModal;$('#t_cal').onchange=e=>$('#t_calbox').hidden=!e.target.checked;
 if(t)$('#tdel').onclick=async()=>{if(await confirmBox('Supprimer cette tâche ?')){closeModal();arr('tasks').forEach(x=>{if((x.deps||[]).includes(t.id)){const c=clone(x);c.deps=c.deps.filter(d=>d!==t.id);put('tasks',x.id,c)}});del('tasks',t.id,['a supprimé la tâche',`« ${t.title} »`,'taches'])}};
 $('#tf').onsubmit=e=>{e.preventDefault();const g=k=>$('#t_'+k).value.trim();const multi=k=>$$('input:checked',$('#f_'+k)).map(i=>i.value);
  const w=($('input[name=t_week]:checked')||{}).value||'';const due=g('due');const cal=$('#t_cal').checked,cdate=$('#t_cdate').value,ctime=$('#t_ctime').value;
  const nid=t?t.id:'T'+String(Math.max(0,...arr('tasks').map(x=>parseInt((x.code||'').slice(1))||0))+1).padStart(2,'0');
  const data={...(t?stripId(t):{}),code:t?t.code:nid,title:g('title'),owner:g('owner'),status:g('status'),desc:g('desc'),priority:g('prio'),start:w||(due&&!w?'':''),due:due||(w?addDays(w,4):''),deps:multi('deps'),docs:multi('docs'),reqs:multi('reqs')};
  if(!w&&due)data.start=weekStart(due);
  closeModal();put('tasks',nid,data,[t?'a modifié la tâche':'a créé la tâche',`« ${data.title} »`,'taches']);
  if(cal)put('events',uid('ev'),{title:data.title,date:cdate||data.due||todayISO(),time:ctime||'',type:'travail',who:[data.owner],desc:'Créneau pour la tâche « '+data.title+' »',taskId:nid},['a ajouté à l\'agenda',`« ${data.title} »`,'taches'])};
 setTimeout(()=>$('#t_title').focus(),60)}

/* Agenda */
let AG={y:new Date().getFullYear(),m:new Date().getMonth()};
const EV_TYPES=[['ap','Séance AP','#2d5bd8'],['reunion','Réunion','#8b4fd1'],['travail','Travail sur une tâche','#16875f'],['rendu','Rendu','#d9822b'],['oral','Oral','#c23b3b']];
function tvAgenda(){
 const first=new Date(AG.y,AG.m,1),start=new Date(first);start.setDate(1-((first.getDay()+6)%7));
 const cells=[...Array(42)].map((_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d});
 const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 const evs=arr('events'),T=filtTasks();
 $('#tv').innerHTML=`<div class="row between" style="margin-bottom:12px"><div class="row"><button class="btn icon" onclick="AG.m--;if(AG.m<0){AG.m=11;AG.y--}renderView()" aria-label="Mois précédent">‹</button><h2 style="min-width:180px;text-align:center;text-transform:capitalize">${first.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</h2><button class="btn icon" onclick="AG.m++;if(AG.m>11){AG.m=0;AG.y++}renderView()" aria-label="Mois suivant">›</button><button class="btn sm ghost" onclick="AG.y=new Date().getFullYear();AG.m=new Date().getMonth();renderView()">Aujourd'hui</button></div>
 <div class="row small">${EV_TYPES.map(t=>`<span><span class="dot" style="background:${t[2]}"></span> ${t[1]}</span>`).join('')}<span><span class="dot" style="background:var(--warn)"></span> Fin d'une tâche</span><button class="btn sm primary" onclick="editEvent(null,'${todayISO()}')">${ui('plus',14)} Événement</button></div></div>
 <div class="cal">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(d=>`<div class="h">${d}</div>`).join('')}${cells.map(d=>{const k=iso(d);const E=evs.filter(e=>e.date===k),TT=T.filter(t=>t.due===k&&!isDone(t.status));return `<div class="d ${d.getMonth()!==AG.m?'out':''} ${k===todayISO()?'today':''}" onclick="if(event.target===this||event.target.classList.contains('dn'))editEvent(null,'${k}')"><span class="dn">${d.getDate()}</span>${E.map(e=>{const ty=EV_TYPES.find(x=>x[0]===e.type)||EV_TYPES[1];return `<span class="ev" style="--ec:${ty[2]}" onclick="event.stopPropagation();editEvent('${e.id}')">${e.time?e.time+' ':''}${esc(e.title)}</span>`}).join('')}${TT.map(t=>`<span class="ev" style="--ec:var(--warn)" onclick="event.stopPropagation();editTask('${t.id}')">⚑ ${esc(t.title)}</span>`).join('')}</div>`}).join('')}</div>`}
function gcalLink(e){const d=e.date.replace(/-/g,'');const t=s=>(s||'').replace(':','')+'00';const dates=e.time?`${d}T${t(e.time)}/${d}T${t(e.end||e.time)}`:`${d}/${d}`;return `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent('[Veau] '+e.title)}&dates=${dates}&details=${encodeURIComponent(e.desc||'')}&ctz=Europe/Paris`}
function editEvent(id,date){const e=id?D.events.get(id):null;
 openForm({title:e?'Événement':'Nouvel événement',values:e||{date,type:'ap',who:members().map(m=>m.id)},
  fields:[{k:'title',label:'Titre',wide:true},{k:'type',label:'Type',type:'select',options:EV_TYPES.map(t=>({v:t[0],l:t[1]}))},{k:'date',label:'Date',type:'date'},{k:'time',label:'Début',type:'time'},{k:'end',label:'Fin',type:'time'},{k:'desc',label:'Notes',type:'textarea',wide:true},{k:'who',label:'Participants',type:'multi',options:members().map(m=>({v:m.id,l:m.name}))}],
  extra:e?`<div class="field wide"><a class="btn" href="${gcalLink(e)}" target="_blank" rel="noopener">${ui('calendar',16)} Ajouter à mon Google Agenda</a></div>`:'',
  onSave:v=>put('events',e?e.id:uid('ev'),{...(e?stripId(e):{}),...v},[e?'a modifié l\'événement':'a ajouté à l\'agenda',`« ${v.title} » (${fmtD(v.date)})`,'taches']),
  onDelete:e?()=>del('events',e.id,['a supprimé l\'événement',`« ${e.title} »`,'taches']):null})}

/* ===================== DOCUMENTS ===================== */
let DU={q:'',folder:''};
const DOC_TYPES=[['gdoc','Document','#2d6be0','DOC'],['gsheet','Tableur','#16875f','XLS'],['gslides','Présentation','#d9822b','PPT'],['pdf','PDF','#c23b3b','PDF'],['schema','Schéma','#8b4fd1','SCH'],['autre','Autre','#475569','…']];
const DOC_ST=[['brouillon','Brouillon'],['encours','En cours'],['review','À relire'],['valide','Validé'],['source','Consigne des profs']];
VIEWS.documents=function(){
 const L=arr('docs').filter(d=>(!DU.folder||d.folder===DU.folder)&&(!DU.q||norm(d.title+' '+(d.notes||'')).includes(norm(DU.q))));
 const card=(d,i)=>{const ty=DOC_TYPES.find(t=>t[0]===d.type)||DOC_TYPES[5];return `<div class="card hover doc" style="--i:${i}"><span class="doc-ico" style="background:${ty[2]}">${ty[3]}</span><div class="doc-body"><a href="javascript:void 0" onclick="editDoc('${d.id}')" class="doc-title">${esc(d.title)}</a><div class="tiny muted">${esc(d.notes?trunc(d.notes,90):ty[1])}</div><div class="row" style="gap:5px;margin-top:8px"><span class="chip ${d.status==='valide'?'ok':d.status==='review'?'warn':d.status==='source'?'acc':''}">${stL(DOC_ST,d.status)}</span>${d.owner&&d.owner!=='all'?`<span class="chip">${esc(member(d.owner).name)}</span>`:''}</div></div>${d.url?`<a class="btn sm" href="${esc(d.url)}" target="_blank" rel="noopener">${ui('ext',14)} Ouvrir</a>`:'<span class="chip warn" title="Colle le lien Drive du fichier">Pas de lien</span>'}</div>`};
 const groups=DRIVE.folders.map(f=>[f,L.filter(d=>d.folder===f[0])]).filter(g=>g[1].length);
 $('#view').innerHTML=pageHead('Documents','Tous les fichiers du projet. Ils s\'ouvrent dans Google Drive.',`<button class="btn primary" onclick="editDoc()">${ui('plus',16)} Ajouter un document</button>`)+
 `<section class="block">${folderHub(true)}</section>
 <div class="row" style="margin-bottom:16px"><div class="seg">${[['','Tous'],...DRIVE.folders.map(f=>[f[0],f[0]+' · '+f[1]])].map(([k,l])=>`<button class="${DU.folder===k?'on':''}" onclick="DU.folder='${k}';renderView()">${esc(l)}</button>`).join('')}</div><input style="max-width:240px" placeholder="Rechercher un document…" value="${esc(DU.q)}" onchange="DU.q=this.value;renderView()"></div>
 ${groups.map(([f,docs])=>`<section class="block"><div class="block-head"><h2><span class="fdot" style="background:${f[3]}"></span>${f[0]} · ${esc(f[1])}</h2><a class="small" href="${folderUrl(f[2])}" target="_blank" rel="noopener">Ouvrir le dossier ${ui('ext',12)}</a></div><div class="grid g-2 stagger">${docs.map(card).join('')}</div></section>`).join('')||'<div class="empty">Aucun document trouvé.</div>'}
 <p class="small muted" style="margin-top:20px">${ui('link',14)} Pour que tes camarades ouvrent les documents : dans Drive, partage le dossier du projet avec eux en « Éditeur », ou choisis « Tous les utilisateurs disposant du lien ».</p>`;
};
function editDoc(id){const d=id?D.docs.get(id):null;
 openForm({title:d?'Document':'Ajouter un document',values:d||{type:'gdoc',status:'brouillon',owner:ME.id,folder:'4'},
  fields:[{k:'title',label:'Nom du document',wide:true},{k:'url',label:'Lien Google Drive',type:'url',wide:true,hint:'Dans Drive : clic droit sur le fichier › Partager › Copier le lien.'},{k:'folder',label:'Dossier',type:'select',options:DRIVE.folders.map(f=>({v:f[0],l:f[0]+' · '+f[1]}))},{k:'type',label:'Type',type:'select',options:DOC_TYPES.map(t=>({v:t[0],l:t[1]}))},{k:'status',label:'Statut',type:'select',options:DOC_ST.map(s=>({v:s[0],l:s[1]}))},{k:'owner',label:'Responsable',type:'select',options:memberOpts()},{k:'notes',label:'En deux mots, il contient…',type:'textarea',wide:true}],
  onSave:v=>put('docs',d?d.id:uid('doc'),{...(d?stripId(d):{}),...v},[d?'a mis à jour le document':'a ajouté le document',`« ${v.title} »`,'documents']),
  onDelete:d?()=>del('docs',d.id,['a retiré le document',`« ${d.title} »`,'documents']):null})}

/* ===================== LE PROJET ===================== */
let PJ={tab:'exigences',sec:''};
const setPJ=k=>{PJ.tab=k;renderView()};
VIEWS.projet=function(){
 $('#view').innerHTML=pageHead('Le projet','Ce que demande la mairie, ce que nous avons décidé, et l\'analyse du besoin de chaque service.')+`<div style="margin-bottom:20px">${tabsHtml([['exigences','Ce que demande la mairie','req'],['decisions','Nos décisions','decision'],['qqoqcp','Analyse du besoin','qq']],PJ.tab,'setPJ')}</div><div id="pv"></div>`;
 ({exigences:pvReqs,decisions:pvDecisions,qqoqcp:pvQQ})[PJ.tab]();
 if(HL){const el=document.getElementById('hl-'+HL);if(el){el.scrollIntoView({block:'center',behavior:'smooth'});el.classList.add('hl')}HL=null}
};
function pvReqs(){const T=arr('tasks'),Dd=arr('decisions');const SECS=[['','Toutes'],['§2','Les besoins'],['§4','Les règles pour tout le SI'],['§5','Les contraintes']];
 const L=REQS.filter(r=>!PJ.sec||r.section.startsWith(PJ.sec));
 $('#pv').innerHTML=`<div class="explain">${ui('spark',18)}<div><b>À quoi ça sert ?</b> Le cahier des charges contient 20 exigences. Les profs veulent que <b>chaque choix technique réponde à une exigence</b>. On les a numérotées (EX-01…) pour pouvoir les citer à l'oral et dans les décisions.</div></div>
 <div class="seg" style="margin-bottom:16px">${SECS.map(([k,l])=>`<button class="${PJ.sec===k?'on':''}" onclick="PJ.sec='${k}';renderView()">${l}</button>`).join('')}</div>
 <div class="grid g-2 stagger">${L.map((r,i)=>{const t=T.filter(x=>(x.reqs||[]).includes(r.id)),d=Dd.filter(x=>(x.reqs||[]).includes(r.id));return `<article class="card req" id="hl-${r.id}" style="--i:${i}"><div class="row between"><span class="code-pill">${r.id}</span>${t.length||d.length?`<span class="chip ok">Prise en compte</span>`:'<span class="chip">Pas encore traitée</span>'}</div>
 <h3>${esc(r.domain)}</h3><p class="plain">${esc(r.plain)}</p><div class="bib-line">${icon('building',22)}<span><b>Pour la bibliothèque :</b> ${esc(r.bib)}</span></div>
 <details><summary class="tiny">Texte exact du cahier des charges (${r.section})</summary><p class="small muted">« ${esc(r.text)} »</p></details>
 ${d.length||t.length?`<div class="row" style="gap:5px;margin-top:8px">${d.map(x=>`<a class="chip acc" href="#projet" onclick="PJ.tab='decisions';HL='${x.code}'">${x.code}</a>`).join('')}${t.map(x=>`<span class="chip" title="${esc(x.title)}">${esc(trunc(x.title,28))}</span>`).join('')}</div>`:''}</article>`}).join('')}</div>`}
const DEC_F=[['title','Titre'],['problem','Problème'],['solution','Ce qu\'on propose'],['justification','Pourquoi'],['alternatives','Autres options'],['consequences','Conséquences'],['owner','Responsable'],['status','Statut']];
function pvDecisions(){const L=arr('decisions').sort((a,b)=>a.code.localeCompare(b.code));
 $('#pv').innerHTML=`<div class="explain">${ui('decision',18)}<div><b>Une décision = un choix technique + pourquoi.</b> On note le problème, la solution, les exigences qui la justifient et les autres options. Une décision « proposée » attend l'accord du groupe. Chaque modification garde l'ancienne version.</div><button class="btn primary" onclick="editDecision()">${ui('plus',16)} Décision</button></div>
 <div class="grid g-2 stagger">${L.map((d,i)=>`<article class="card dec" id="hl-${d.code}" style="--i:${i}"><div class="row between"><span class="code-pill">${d.code}</span><span class="chip ${stChip(d.status)}">${stL(DEC_ST,d.status)}</span></div><h3>${esc(d.title)}</h3>
 <div class="dec-grid"><div><div class="eyebrow">Le problème</div><p class="small">${esc(d.problem)}</p></div><div><div class="eyebrow">Ce qu'on propose</div><p class="small">${esc(d.solution)}</p></div></div>
 <details><summary class="small">Pourquoi, autres options, conséquences</summary>${[['Pourquoi',d.justification],['Autres options',d.alternatives],['Conséquences',d.consequences]].filter(x=>x[1]).map(([l,v])=>`<div style="margin-top:8px"><div class="eyebrow">${l}</div><p class="small" style="margin:3px 0">${reqLinks(v)}</p></div>`).join('')}</details>
 <div class="row between" style="margin-top:12px"><div class="row" style="gap:5px">${who(d.owner)}${(d.reqs||[]).map(r=>`<a class="chip acc" href="#projet" onclick="PJ.tab='exigences';HL='${r}'">${r}</a>`).join('')}</div><div class="row" style="gap:6px">${d.status==='proposee'?`<button class="btn sm" onclick="validateDecision('${d.id}')">✓ Valider</button>`:''}<button class="btn sm ghost" title="Modifier" onclick="editDecision('${d.id}')">${ui('edit',14)}</button><button class="btn sm ghost" title="Historique" onclick="showHistory('${d.id}')" ${(d.history||[]).length?'':'disabled'}>${ui('history',14)} ${(d.history||[]).length}</button></div></div></article>`).join('')||'<div class="empty">Aucune décision.</div>'}</div>`}
function snapDec(d){const s={};DEC_F.forEach(([k])=>s[k]=d[k]);return [{at:d.updatedAt||Date.now(),by:d.updatedBy||'',data:s},...(d.history||[])].slice(0,25)}
function validateDecision(id){const d=D.decisions.get(id);put('decisions',id,{...stripId(d),status:'validee',history:snapDec(d)},['a validé la décision',d.code+' · '+d.title,'projet'])}
function editDecision(id){const d=id?D.decisions.get(id):null;
 openForm({title:d?`Décision ${d.code}`:'Nouvelle décision',wide:true,values:d||{status:'proposee',owner:ME.id},
  fields:[{k:'title',label:'Titre',wide:true},{k:'problem',label:'Le problème',type:'textarea',wide:true},{k:'solution',label:'Ce qu\'on propose',type:'textarea',wide:true},{k:'justification',label:'Pourquoi (cite les exigences EX-xx)',type:'textarea',wide:true},{k:'alternatives',label:'Autres options envisagées',type:'textarea'},{k:'consequences',label:'Conséquences / documents à mettre à jour',type:'textarea'},{k:'owner',label:'Responsable',type:'select',options:memberOpts()},{k:'status',label:'Statut',type:'select',options:DEC_ST.map(s=>({v:s[0],l:s[1]}))},{k:'reqs',label:'Exigences',type:'multi',options:REQS.map(r=>({v:r.id,l:`${r.id} · ${r.domain}`}))},{k:'docs',label:'Documents',type:'multi',options:arr('docs').map(x=>({v:x.id,l:x.title}))}],
  onSave:v=>{if(d)put('decisions',d.id,{...stripId(d),...v,history:snapDec(d)},['a modifié la décision',d.code+' · '+v.title,'projet']);
   else{const n=Math.max(0,...arr('decisions').map(x=>parseInt(x.code.slice(2))||0))+1;const code='D-'+String(n).padStart(3,'0');put('decisions',code,{code,...v,history:[]},['a proposé la décision',code+' · '+v.title,'projet'])}},
  onDelete:d?()=>del('decisions',d.id,['a supprimé la décision',d.code,'projet']):null})}
function showHistory(id){const d=D.decisions.get(id);const V=[{at:d.updatedAt,by:d.updatedBy,data:d,cur:true},...(d.history||[])];
 openModal('Historique de '+d.code,V.map((v,i)=>{const prev=V[i+1];const ch=prev?DEC_F.filter(([k])=>(v.data[k]||'')!==(prev.data[k]||'')):DEC_F;
  return `<div class="card" style="margin-bottom:12px;padding:14px"><div class="row between"><b>${v.cur?'Version actuelle':'Ancienne version'}</b><span class="tiny muted">${v.by?esc(v.by)+' · ':''}${v.at?new Date(v.at).toLocaleString('fr-FR'):''}</span></div>${prev?`<div class="tiny muted" style="margin:4px 0">Changé ensuite : ${ch.map(c=>c[1]).join(', ')||'rien'}</div>`:''}${(prev?ch:DEC_F).map(([k,l])=>`<div class="small" style="margin-top:5px"><b>${l} :</b> ${esc(k==='owner'?member(v.data[k]).name:k==='status'?stL(DEC_ST,v.data[k]):v.data[k]||'—')}</div>`).join('')}</div>`}).join(''),true)}
let QS='svc-bib';const QQ_ST=[['vide','Pas encore répondu'],['fait','Écrit dans le CDC'],['hypothese','Supposé par nous'],['a_valider','À valider']];const DIMS=[['Qui','Qui utilise ? Qui gère ?','team'],['Quoi','Quels besoins, quelles données ?','docs'],['Où','Dans quels espaces ?','plan'],['Quand','À quels moments ?','calendar'],['Comment','Comment ça marche ?','topo'],['Pourquoi','À quelle exigence ça répond ?','req']];
function pvQQ(){const S=arr('qq');if(!D.qq.get(QS))QS=S[0]?.id;const s=D.qq.get(QS);
 $('#pv').innerHTML=`<div class="explain">${ui('qq',18)}<div><b>À quoi ça sert ?</b> Avant de choisir le matériel, on décrit le besoin d'un service avec 6 questions : <b>Qui ? Quoi ? Où ? Quand ? Comment ? Pourquoi ?</b> Ça évite d'installer des choses inutiles, et ça prouve aux profs que nos choix viennent du besoin. Pour chaque réponse, indique si c'est écrit dans le CDC, supposé par nous, ou à valider.</div></div>
 <div class="row" style="margin-bottom:16px"><select style="width:auto" onchange="QS=this.value;renderView()">${S.map(x=>`<option value="${x.id}" ${x.id===QS?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="btn" onclick="addService()">${ui('plus',16)} Analyser un autre service</button></div>
 ${!s?'<div class="empty">Aucune analyse.</div>':`<div class="grid g-3 stagger">${DIMS.map(([dm,sub,ic],k)=>`<div class="card qq" style="--i:${k}"><div class="row between" style="flex-wrap:nowrap"><div class="row" style="gap:10px;flex-wrap:nowrap"><span class="qq-ico">${ui(ic,18)}</span><div><h3>${dm} ?</h3><div class="tiny muted">${sub}</div></div></div><button class="btn sm ghost" title="Ajouter une question" onclick="addQQ('${dm}')">${ui('plus',14)}</button></div>
 ${s.items.map((it,i)=>it.dim!==dm?'':`<div class="qq-item"><div class="row between" style="flex-wrap:nowrap;align-items:flex-start"><b class="small">${esc(it.q)}</b><button class="btn ghost icon sm" title="Supprimer" onclick="delQQ(${i})">${ui('close',13)}</button></div><textarea rows="3" placeholder="Votre réponse…" onchange="setQQ(${i},'a',this.value)">${esc(it.a)}</textarea><select class="qq-st st-${it.status}" onchange="setQQ(${i},'status',this.value)">${QQ_ST.map(([k,l])=>`<option value="${k}" ${it.status===k?'selected':''}>${l}</option>`).join('')}</select></div>`).join('')}</div>`).join('')}</div>`}`}
function saveQQ(s,act){put('qq',s.id,stripId(s),act)}
function setQQ(i,k,v){const s=clone(D.qq.get(QS));s.items[i][k]=v;if(k==='a'&&v&&s.items[i].status==='vide')s.items[i].status='hypothese';saveQQ(s,k==='a'?['a complété l\'analyse',`${s.name} : ${trunc(s.items[i].q,40)}`,'projet']:null)}
async function addQQ(dm){const q=await promptBox(`Nouvelle question « ${dm} ? »`);if(!q)return;const s=clone(D.qq.get(QS));s.items.push({dim:dm,q,a:'',status:'vide'});saveQQ(s,['a ajouté une question d\'analyse',s.name,'projet'])}
async function delQQ(i){if(!await confirmBox('Supprimer cette question ?'))return;const s=clone(D.qq.get(QS));s.items.splice(i,1);saveQQ(s)}
async function addService(){const n=await promptBox('Quel service analyser ? (ex. Mairie centrale)');if(!n)return;const id='svc-'+slug(n);const G={Qui:'Qui sont les utilisateurs et les responsables ?',Quoi:'Quels besoins et quelles données ?',Où:'Où sont les postes et les données ?',Quand:'Quand le service doit-il fonctionner ?',Comment:'Comment le service est-il relié à la mairie ?',Pourquoi:'À quelles exigences répondent nos choix ?'};
 await put('qq',id,{name:n,items:DIMS.map(([d])=>({dim:d,q:G[d],a:'',status:'vide'}))},['a commencé l\'analyse de',n,'projet']);QS=id;renderView()}

/* ===================== FEUILLE DE ROUTE ===================== */
let FR={who:null,filter:''};
const frKey=()=>slug(FR.who||ME.name);
const frItems=()=>D.fr.get(frKey())?.items||{};
const FR_ST=[['todo','Pas commencé','#94a3b8'],['doing','En cours','#2d5bd8'],['done','Prêt','#d9822b'],['validated','Validé par le prof','#16875f']];
VIEWS.feuille=function(){
 const I=frItems();const comp=CHECK_DEFS.filter(c=>c.cat==='competence');const liv=CHECK_DEFS.filter(c=>c.cat==='livrable');const mine=!FR.who||FR.who===ME.name;
 const cnt=k=>comp.filter(c=>(I[c.id]?.status||'todo')===k).length;const crit=c=>CRIT.filter(([k])=>I[c.id]?.criteria?.[k]).length;
 const L=comp.filter(c=>!FR.filter||(I[c.id]?.status||'todo')===FR.filter);
 const people=[...new Set([ME.name,...members().map(m=>m.name)])];
 $('#view').innerHTML=pageHead('Feuille de route','La liste officielle des éléments sur lesquels les profs peuvent vous interroger, chacun individuellement.')+
 `<div class="explain">${ui('check',18)}<div><b>Comment ça marche ?</b> La feuille de route contient <b>30 éléments</b> (un service d'authentification, une base de données, une sauvegarde…). Pour chacun, <b>chaque élève</b> doit pouvoir : le montrer dans son lab, l'installer, le configurer, l'expliquer, l'utiliser, et l'avoir décrit dans une procédure de son e-portfolio. <b>Sans procédure, l'élément ne compte pas.</b> Clique sur un élément pour cocher ce que tu sais faire : ta progression est personnelle.</div></div>
 <section class="block"><div class="block-head"><h2>Les 4 livrables du groupe</h2><span class="small muted">Ce que le cahier des charges demande de rendre</span></div><div class="grid g-4">${liv.map(c=>{const s=D.chk.get(c.id)||{};const st=s.status||'todo';const col=FR_ST.find(x=>x[0]===st)?.[2];return `<div class="card liv" style="--c:${col}"><span class="code-pill">${c.id}</span><p class="small" style="margin:10px 0 12px">${esc(c.title)}</p><div class="stack" style="gap:8px"><select onchange="setLiv('${c.id}','owner',this.value)">${memberOpts().map(o=>`<option value="${o.v}" ${(s.owner??c.owner)===o.v?'selected':''}>${esc(o.v?member(o.v).name:'Personne')}</option>`).join('')}</select><select onchange="setLiv('${c.id}','status',this.value)">${FR_ST.map(x=>`<option value="${x[0]}" ${st===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div></div>`}).join('')}</div></section>
 <section class="block"><div class="block-head"><h2>${mine?'Ma feuille de route':'Feuille de route de '+esc(FR.who)}</h2><select style="width:auto" onchange="FR.who=this.value;renderView()">${people.map(n=>`<option ${(FR.who||ME.name)===n?'selected':''}>${esc(n)}</option>`).join('')}</select></div>
 <div class="fr-summary">${FR_ST.map(([k,l,c])=>`<button class="fr-sum ${FR.filter===k?'on':''}" style="--c:${c}" onclick="FR.filter=FR.filter==='${k}'?'':'${k}';renderView()"><b>${cnt(k)}</b><span>${l}</span></button>`).join('')}</div>
 <div class="grid g-3 stagger">${L.map((c,i)=>{const st=I[c.id]?.status||'todo';const col=FR_ST.find(x=>x[0]===st)[2];const n=crit(c);return `<button class="card hover comp" style="--i:${i};--c:${col}" ${mine?`onclick="editComp('${c.id}')"`:'disabled'}><div class="row between"><span class="code-pill">${c.id.replace('C','n°')}</span><span class="chip" style="color:${col}">${FR_ST.find(x=>x[0]===st)[1]}</span></div><p>${esc(c.title)}</p><div class="dots" title="${n} critère(s) sur 7">${CRIT.map(([k])=>`<i class="${I[c.id]?.criteria?.[k]?'on':''}"></i>`).join('')}<span class="tiny muted">${n}/7</span></div></button>`}).join('')}</div></section>`;
};
function setLiv(id,k,v){const c=clone(D.chk.get(id))||{};c[k]=v;put('chk',id,c,k==='status'?['a mis à jour le livrable',id,'feuille']:null)}
function editComp(id){const c=CHECK_DEFS.find(x=>x.id===id);const it=frItems()[id]||{};
 const o=openModal(c.id.replace('C','Élément n°'),`<form id="cf"><p style="margin-top:0;font-size:16px;font-weight:600">${esc(c.title)}</p><div class="eyebrow" style="margin:14px 0 8px">Ce que je sais faire</div>
 ${CRIT.map(([k,l],i)=>`<label class="crit-row"><input type="checkbox" name="${k}" ${it.criteria?.[k]?'checked':''}><span>${esc(l)}</span>${i>=5?'<span class="chip bad">obligatoire</span>':''}</label>`).join('')}
 <div class="grid g-2" style="margin-top:14px"><label class="field"><span>Où j'en suis</span><select id="c_st">${FR_ST.map(x=>`<option value="${x[0]}" ${(it.status||'todo')===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label class="field"><span>Lien vers ma procédure</span><input id="c_proof" value="${esc(it.proof||'')}" placeholder="https://…"></label></div>
 <div class="row" style="justify-content:flex-end;margin-top:16px"><button type="button" class="btn" data-x>Annuler</button><button class="btn primary">Enregistrer</button></div></form>`);
 $('[data-x]',o).onclick=closeModal;
 $('#cf').onsubmit=e=>{e.preventDefault();const crit={};CRIT.forEach(([k])=>crit[k]=$(`input[name=${k}]`).checked);const k=slug(ME.name);const doc=clone(D.fr.get(k))||{name:ME.name,items:{}};doc.name=ME.name;doc.items[id]={status:$('#c_st').value,criteria:crit,proof:$('#c_proof').value.trim()};closeModal();put('fr',k,doc,['a avancé sur la feuille de route',`${c.id.replace('C','n°')} · ${trunc(c.title,40)}`,'feuille'])}}

