let RU={tab:'questions',cat:'',weak:false,open:null,fb:null,showRef:false},quiz=null,simu=null,timers=[];
const allQuestions=()=>{const m=new Map(BASE_QUESTIONS.map(q=>[q.id,q]));arr('questions').forEach(q=>m.set(q.id,{...m.get(q.id),...q}));return [...m.values()].filter(q=>!q.deleted&&q.elements).sort((a,b)=>a.id.localeCompare(b.id))};
const myProg=()=>D.progress.get(slug(ME.name))?.q||{};
const LV=['À revoir','Fragile','Correct','Maîtrisé'];const lvl=s=>s==null?null:s<.4?0:s<.7?1:s<.9?2:3;
const lvChip=l=>l==null?'<span class="chip">Pas encore essayé</span>':`<span class="chip ${['bad','warn','acc','ok'][l]}">${LV[l]}</span>`;
const TECH=[['pfSense','pfsense'],['OPNsense','opnsense'],['GLPI','glpi'],['Zabbix','zabbix'],['Nagios','nagios'],['Proxmox','proxmox'],['Active Directory','active directory'],['Nextcloud','nextcloud'],['MariaDB','mariadb'],['MySQL','mysql'],['PostgreSQL','postgres'],['Koha','koha'],['Suricata','suricata'],['Snort','snort'],['WireGuard','wireguard'],['OpenVPN','openvpn'],['IPsec','ipsec'],['Apache','apache'],['Nginx','nginx'],['HAProxy','haproxy'],['Veeam','veeam'],['Wazuh','wazuh'],['ntopng','ntopng'],['Clonezilla','clonezilla'],['Windows Server','windows server'],['Debian','debian'],['Ubuntu','ubuntu'],['Cisco','cisco']];
function evaluate(q,text){const t=' '+norm(text).replace(/\s+/g,' ')+' ';const res=q.elements.map(el=>({el,ok:el.k.some(k=>t.includes(norm(k)))}));const score=res.length?res.filter(r=>r.ok).length/res.length:0;
 const pit=(q.pitfalls||[]).filter(p=>p.all.every(k=>t.includes(norm(k)))&&!(p.none||[]).some(k=>t.includes(norm(k))));
 const abs=['toujours','jamais','100 %','100%','totalement securise','impossible','aucun risque','infaillible','inviolable'].filter(w=>t.includes(norm(w)));
 const corpus=norm(JSON.stringify([arr('decisions'),arr('sites'),arr('docs').map(d=>d.title+' '+(d.notes||''))]));
 const techs=TECH.filter(([n,k])=>t.includes(k)&&!corpus.includes(k)).map(x=>x[0]);const words=norm(text).split(/\s+/).filter(Boolean).length;
 const justif=/(parce que|car |afin de|pour |exigence|ex-\d|cahier des charges|cdc|besoin)/.test(t);return{res,score,pit,abs,techs,words,justif}}
async function saveProgress(qid,score,oral){const k=slug(ME.name);const p=clone(D.progress.get(k))||{name:ME.name,q:{}};const e=p.q[qid]||{at:[]};e.at=[{ts:Date.now(),s:Math.round(score*100)/100,o:!!oral},...(e.at||[])].slice(0,15);e.m=lvl(score);p.q[qid]=e;p.name=ME.name;await put('progress',k,p)}
const setRU=k=>{RU.tab=k;RU.open=null;quiz=null;simu=null;renderView()};
VIEWS.revision=function(){timers.forEach(clearInterval);timers=[];
 $('#view').innerHTML=pageHead('Révision de l\'oral','Entraîne-toi à expliquer nos choix avec tes propres mots. L\'application te dit ce qui manque et où le retrouver.')+`<div style="margin-bottom:20px">${tabsHtml([['questions','Questions','qq'],['aleatoire','Au hasard','rotate'],['quiz','Quiz','check'],['simu','Simulation d\'oral','learn'],['progres','Ma progression','spark']],RU.tab,'setRU')}</div><div id="rv"></div>`;
 ({questions:rvList,aleatoire:rvRandom,quiz:rvQuiz,simu:rvSimu,progres:rvProgress})[RU.tab]()};
function rvList(){if(RU.open)return rvDetail(RU.open);const P=myProg();const Q=allQuestions();const cats=[...new Set(Q.map(q=>q.cat))];
 const L=Q.filter(q=>(!RU.cat||q.cat===RU.cat)&&(!RU.weak||P[q.id]?.m==null||P[q.id].m<=1));
 $('#rv').innerHTML=`<div class="row" style="margin-bottom:14px"><select style="width:auto" onchange="RU.cat=this.value;renderView()"><option value="">Tous les thèmes</option>${cats.map(c=>`<option ${RU.cat===c?'selected':''}>${esc(c)}</option>`).join('')}</select><label class="row small"><input type="checkbox" ${RU.weak?'checked':''} onchange="RU.weak=this.checked;renderView()"> Seulement celles à retravailler</label><span style="flex:1"></span><button class="btn" onclick="editQuestion()">${ui('plus',16)} Question</button></div>
 <div class="grid g-2 stagger">${L.map((q,i)=>`<button class="card hover qcard" style="--i:${i}" onclick="RU.open='${q.id}';RU.fb=null;RU.showRef=false;renderView()"><div class="row between"><span class="chip">${esc(q.cat)}</span>${lvChip(P[q.id]?.m)}</div><div class="qtxt">${esc(q.q)}</div>${q.refStatus==='a_valider'?'<span class="tiny muted">Réponse issue du cours, à vérifier</span>':''}</button>`).join('')}</div>`}
function rvDetail(id){const q=allQuestions().find(x=>x.id===id);const P=myProg()[id];const fb=RU.fb;const draft=ls.get('veau-draft-'+id,'');
 $('#rv').innerHTML=`<button class="btn sm ghost" onclick="RU.open=null;renderView()">‹ Toutes les questions</button>
 <div class="card" style="margin-top:12px;max-width:900px"><div class="row between"><span class="row" style="gap:6px"><span class="chip">${esc(q.cat)}</span>${q.refStatus==='a_valider'?'<span class="chip warn">Réponse issue du cours, à vérifier</span>':'<span class="chip ok">Réponse tirée de nos documents</span>'}</span><span class="row">${lvChip(P?.m)}<button class="btn sm ghost" title="Modifier la question" onclick="editQuestion('${q.id}')">${ui('edit',14)}</button></span></div>
 <h2 style="margin:16px 0;font-size:22px">${esc(q.q)}</h2>
 <textarea id="mine" rows="7" placeholder="Réponds comme si tu parlais au professeur…" oninput="ls.set('veau-draft-${id}',this.value)">${esc(draft)}</textarea>
 <div class="row" style="margin-top:12px"><button class="btn primary" onclick="checkAnswer('${q.id}')">Vérifier ma réponse</button>${P?.at?.length?`<span class="small muted">${P.at.length} essai(s) · dernier ${Math.round(P.at[0].s*100)} %</span>`:''}</div>
 ${fb?renderFeedback(fb):''}
 ${fb||P?.at?.length?`<div style="margin-top:16px"><button class="btn" onclick="RU.showRef=!RU.showRef;renderView()">${RU.showRef?'Masquer':'Voir'} la réponse de référence</button></div>${RU.showRef?`<div class="ref" style="margin-top:12px">${reqLinks(q.ref)}</div><p class="small"><b>À retenir :</b> ${esc(q.expl)}</p>`:''}`:'<p class="small muted" style="margin-top:14px">La réponse de référence s\'affiche après ton premier essai.</p>'}
 <details style="margin-top:14px"><summary class="small">Les idées à ne pas oublier (${q.elements.length})</summary><ul class="small">${q.elements.map(e=>`<li>${esc(e.l)} <span class="muted">· ${reqLinks(e.s)}</span></li>`).join('')}</ul></details></div>`}
function renderFeedback(f){const ok=f.res.filter(r=>r.ok),ko=f.res.filter(r=>!r.ok);
 return `<div style="margin-top:16px"><div class="row"><b>Tu as cité ${ok.length} idée${ok.length>1?'s':''} sur ${f.res.length}</b>${lvChip(lvl(f.score))}</div>
 ${ok.length?`<div class="fb ok"><h4>Bien vu</h4><ul>${ok.map(r=>`<li>${esc(r.el.l)}</li>`).join('')}</ul></div>`:''}
 ${ko.length?`<div class="fb bad"><h4>Il manque</h4><ul>${ko.map(r=>`<li><b>${esc(r.el.l)}</b><br><span class="small">${esc(r.el.w)} · À revoir : ${reqLinks(r.el.s)}</span></li>`).join('')}</ul></div>`:''}
 ${f.pit.length?`<div class="fb warn"><h4>Attention, erreur fréquente</h4><ul>${f.pit.map(p=>`<li>${esc(p.msg)} <i class="small">· ${reqLinks(p.src)}</i></li>`).join('')}</ul></div>`:''}
 ${f.techs.length?`<div class="fb warn"><h4>Pas encore décidé par le groupe</h4><ul><li>Tu cites <b>${f.techs.map(esc).join(', ')}</b>, qui n'apparaît dans aucune de nos décisions. Présente-le comme une proposition.</li></ul></div>`:''}
 ${f.abs.length||!f.justif||f.words<20?`<div class="fb warn"><h4>À améliorer</h4><ul>${f.abs.length?`<li>Évite les formules absolues (« ${f.abs.map(esc).join(' », « ')} »).</li>`:''}${!f.justif?'<li>Dis pourquoi : relie ta réponse à une exigence (EX-xx).</li>':''}${f.words<20?'<li>Ta réponse est très courte : développe.</li>':''}</ul></div>`:''}</div>`}
function checkAnswer(id){const q=allQuestions().find(x=>x.id===id);const f=evaluate(q,$('#mine').value);RU.fb=f;saveProgress(id,f.score);renderView()}
function editQuestion(id){const q=id?allQuestions().find(x=>x.id===id):null;
 openForm({title:q?'Modifier la question':'Nouvelle question',wide:true,values:{...(q||{refStatus:'a_construire',cat:'Bibliothèque'}),elements:q?q.elements.map(e=>[e.l,e.k.join('; '),e.w,e.s].join(' | ')).join('\n'):'',pitfalls:q?(q.pitfalls||[]).map(p=>[p.all.join('; '),(p.none||[]).join('; '),p.msg,p.src].join(' | ')).join('\n'):''},
  fields:[{k:'q',label:'Question du professeur',wide:true},{k:'cat',label:'Thème'},{k:'refStatus',label:'D\'où vient la réponse ?',type:'select',options:[{v:'documente',l:'De nos documents'},{v:'a_valider',l:'Du cours, à vérifier'},{v:'a_construire',l:'À construire'}]},{k:'ref',label:'Réponse de référence',type:'textarea',wide:true,rows:5},{k:'expl',label:'À retenir',type:'textarea',wide:true},
   {k:'elements',label:'Idées attendues : une ligne = Idée | mots-clés; séparés; par ; | pourquoi | source',type:'textarea',wide:true,rows:6},{k:'pitfalls',label:'Erreurs à repérer : mots présents; … | mots absents; … | message | source',type:'textarea',wide:true,rows:3}],
  onSave:v=>{const els=v.elements.split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(a=>a[0]).map(([l,k='',w='',s=''])=>({l,k:k.split(';').map(x=>x.trim()).filter(Boolean),w,s}));const pits=v.pitfalls.split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(a=>a[0]).map(([a,n='',m='',s=''])=>({all:a.split(';').map(x=>x.trim()).filter(Boolean),none:n.split(';').map(x=>x.trim()).filter(Boolean),msg:m,src:s}));
   const nid=q?q.id:'Q'+String(Math.max(0,...allQuestions().map(x=>parseInt(x.id.slice(1))||0))+1).padStart(2,'0');put('questions',nid,{id:nid,q:v.q,cat:v.cat,refStatus:v.refStatus,ref:v.ref,expl:v.expl,elements:els,pitfalls:pits},[q?'a modifié la question':'a ajouté la question',v.q,'revision'])},
  onDelete:q?()=>{put('questions',q.id,{id:q.id,deleted:true},['a supprimé la question',q.q,'revision']);RU.open=null}:null})}
function rvRandom(){const P=myProg();const Q=allQuestions();const pool=Q.filter(q=>P[q.id]?.m==null||P[q.id].m<3);const L=pool.length?pool:Q;const q=L[Math.floor(Math.random()*L.length)];
 $('#rv').innerHTML=`<div class="card spot"><div class="eyebrow">Question tirée au hasard</div><h2>${esc(q.q)}</h2><div class="row" style="justify-content:center"><button class="btn primary" onclick="RU.tab='questions';RU.open='${q.id}';RU.fb=null;RU.showRef=false;renderView()">Répondre</button><button class="btn" onclick="renderView()">${ui('rotate',16)} Une autre</button></div></div>`}
function rvQuiz(){
 if(!quiz){$('#rv').innerHTML=`<div class="card spot"><h2>Quiz rapide</h2><p class="muted">${QCM.length} questions à choix multiples sur le projet.</p><button class="btn primary" onclick="quiz={o:QCM.map(x=>x.id).sort(()=>Math.random()-.5),i:0,s:0,a:null};renderView()">Commencer</button></div>`;return}
 if(quiz.i>=quiz.o.length){$('#rv').innerHTML=`<div class="card spot">${ringSvg(quiz.s/quiz.o.length,110,'var(--ok)')}<h2>${quiz.s}/${quiz.o.length}</h2><button class="btn primary" onclick="quiz=null;renderView()">Recommencer</button></div>`;animateRings();return}
 const m=QCM.find(x=>x.id===quiz.o[quiz.i]);
 $('#rv').innerHTML=`<div class="card" style="max-width:720px;margin:0 auto"><div class="row between"><span class="eyebrow">Question ${quiz.i+1} / ${quiz.o.length}</span><span class="chip ok">${quiz.s} bonne${quiz.s>1?'s':''}</span></div><div class="bar" style="margin:12px 0 18px"><i style="width:${quiz.i/quiz.o.length*100}%"></i></div><h2 style="font-size:20px">${esc(m.q)}</h2>
 ${m.c.map((c,i)=>`<button class="choice ${quiz.a!=null?(i===m.a?'good':i===quiz.a?'badc':''):''}" ${quiz.a!=null?'disabled':''} onclick="quiz.a=${i};if(${i}===${m.a})quiz.s++;renderView()">${esc(c)}</button>`).join('')}
 ${quiz.a!=null?`<div class="row between" style="margin-top:12px"><span class="small">${quiz.a===m.a?'Bonne réponse.':'Ce n\'est pas ça.'} Source : ${reqLinks(m.src)}</span><button class="btn primary" onclick="quiz.i++;quiz.a=null;renderView()">Suivante ›</button></div>`:''}</div>`}
function rvSimu(){
 if(!simu){$('#rv').innerHTML=`<div class="card spot"><h2>Simulation d'oral</h2><p class="muted">Des questions au hasard, 2 minutes chacune. Réponds à voix haute, puis coche les idées que tu as vraiment dites.</p><div class="row" style="justify-content:center"><select id="simuN" style="width:auto"><option>3</option><option selected>5</option><option>8</option></select><button class="btn primary" onclick="startSimu(+$('#simuN').value)">Démarrer</button></div></div>`;return}
 if(simu.i>=simu.list.length){const tot=simu.res.reduce((a,b)=>a+b,0)/simu.res.length;const Q=allQuestions();$('#rv').innerHTML=`<div class="card" style="max-width:720px;margin:0 auto"><div class="row">${ringSvg(tot,90)}<div><h2>Résultat : ${Math.round(tot*100)} %</h2><p class="muted small">Les questions faibles reviennent en priorité dans « Au hasard ».</p></div></div><ul class="list" style="margin-top:12px">${simu.list.map((id,i)=>`<li><span class="small">${esc(Q.find(x=>x.id===id).q)}</span>${lvChip(lvl(simu.res[i]))}</li>`).join('')}</ul><button class="btn primary" onclick="simu=null;renderView()">Recommencer</button></div>`;animateRings();return}
 const q=allQuestions().find(x=>x.id===simu.list[simu.i]);
 if(simu.phase==='q'){$('#rv').innerHTML=`<div class="card" style="max-width:720px;margin:0 auto"><div class="row between"><span class="eyebrow">Question ${simu.i+1} / ${simu.list.length}</span><span class="timer" id="tmr">2:00</span></div><h2 style="margin:18px 0;font-size:22px">${esc(q.q)}</h2><textarea id="simuTxt" rows="4" placeholder="Notes (facultatif)…"></textarea><button class="btn primary" style="margin-top:12px" onclick="endSimuQ()">J'ai fini</button></div>`;
  const tick=()=>{const left=Math.max(0,simu.end-Date.now());const el=$('#tmr');if(!el)return;el.textContent=`${Math.floor(left/60000)}:${String(Math.floor(left/1000)%60).padStart(2,'0')}`;el.style.color=left<20000?'var(--bad)':'';if(!left)endSimuQ()};tick();timers.push(setInterval(tick,500))}
 else{$('#rv').innerHTML=`<div class="card" style="max-width:720px;margin:0 auto"><h2>${esc(q.q)}</h2><p class="muted">Coche les idées que tu as vraiment dites :</p>${q.elements.map((e,i)=>`<label class="crit-row"><input type="checkbox" class="se" ${simu.auto[i]?'checked':''}><span>${esc(e.l)}</span></label>`).join('')}<button class="btn primary" style="margin-top:10px" onclick="nextSimu()">Valider ›</button></div>`}}
function startSimu(n){const ids=allQuestions().map(q=>q.id).sort(()=>Math.random()-.5).slice(0,n);simu={list:ids,i:0,res:[],phase:'q',end:Date.now()+120000,auto:[]};renderView()}
function endSimuQ(){if(!simu||simu.phase!=='q')return;timers.forEach(clearInterval);timers=[];const q=allQuestions().find(x=>x.id===simu.list[simu.i]);simu.auto=evaluate(q,$('#simuTxt')?.value||'').res.map(r=>r.ok);simu.phase='check';renderView()}
function nextSimu(){const c=$$('.se');const sc=c.length?c.filter(x=>x.checked).length/c.length:0;simu.res.push(sc);saveProgress(simu.list[simu.i],sc,true);simu.i++;simu.phase='q';simu.end=Date.now()+120000;renderView()}
function rvProgress(){const Q=allQuestions(),P=myProg();const cnt=[null,0,1,2,3].map(l=>Q.filter(q=>(P[q.id]?.m??null)===l).length);const people=arr('progress');
 $('#rv').innerHTML=`<div class="fr-summary" style="margin-bottom:18px">${['Pas encore essayé',...LV].map((l,i)=>`<div class="fr-sum" style="--c:${['#94a3b8','#c23b3b','#d9822b','#2d5bd8','#16875f'][i]}"><b>${cnt[i]}</b><span>${l}</span></div>`).join('')}</div>
 <div class="grid g-2"><div class="card"><h2 style="margin-bottom:8px">Mes questions</h2><ul class="list">${[...Q].sort((a,b)=>(P[a.id]?.m??-1)-(P[b.id]?.m??-1)).map(q=>`<li><a class="small" href="javascript:void 0" onclick="RU.tab='questions';RU.open='${q.id}';RU.fb=null;RU.showRef=false;renderView()">${esc(q.q)}</a>${lvChip(P[q.id]?.m)}</li>`).join('')}</ul></div>
 <div class="card"><h2 style="margin-bottom:8px">Le groupe</h2>${people.map(p=>{const m=Object.values(p.q||{}).filter(x=>x.m===3).length;return `<div style="margin:14px 0"><div class="row between"><span class="who">${avatar(p.name,colorOf(p.name))}${esc(p.name)}</span><span class="small muted">${m}/${Q.length} maîtrisées</span></div><div class="bar" style="margin-top:6px"><i style="width:${m/Q.length*100}%;background:${colorOf(p.name)}"></i></div></div>`}).join('')||'<p class="muted small">Personne ne s\'est encore entraîné.</p>'}</div></div>`}

