VIEWS.equipe=function(){const M=members();
 $('#view').innerHTML=pageHead('Équipe','Qui fait quoi. Chacun peut modifier les noms, rôles et couleurs.')+
 `<div class="grid g-2"><div class="card"><h2 style="margin-bottom:6px">Les membres</h2>${M.map((m,i)=>`<div class="member-row">${avatar(m.name,m.color,'lg')}<div class="grid" style="grid-template-columns:1fr 1.6fr;gap:8px;flex:1"><input value="${esc(m.name)}" onchange="setMember(${i},'name',this.value)" aria-label="Nom"><input value="${esc(m.role)}" onchange="setMember(${i},'role',this.value)" aria-label="Rôle"></div><input type="color" value="${m.color}" style="width:42px;flex:none" onchange="setMember(${i},'color',this.value)" aria-label="Couleur"></div>`).join('')}</div>
 <div class="card"><h2 style="margin-bottom:10px">Donner l'accès au groupe</h2><ol class="steps"><li><b>L'application :</b> bouton <b>Partager</b> de claude.ai, puis invite chaque camarade par e-mail en <b>Éditeur</b> (sinon il peut seulement regarder).</li><li><b>Les documents :</b> dans Drive, partage le <a href="${DRIVE.root}" target="_blank" rel="noopener">dossier du projet</a> en « Éditeur ».</li><li>À l'ouverture, chacun clique sur son nom : ses modifications apparaissent à son nom.</li></ol>
 <h3 style="margin-top:18px">Sauvegarde</h3><p class="small muted">Télécharge toutes les données du projet dans un fichier, à ranger dans le Drive.</p><button class="btn" onclick="exportAll()">${ui('download',16)} Télécharger une sauvegarde</button>
 <h3 style="margin-top:18px">Mon identité</h3><p class="small">Connecté en tant que <b>${esc(ME.name)}</b>. <button class="btn sm ghost" onclick="$('#meBtn').click()">Changer</button></p></div></div>`};
function setMember(i,k,v){const L=clone(members());L[i][k]=v;put('meta','members',{list:L},['a modifié l\'équipe',L[i].name,'equipe'])}
function exportAll(){const o={exportedAt:new Date().toISOString(),by:ME.name};COLS.forEach(c=>o[c]=arr(c));saveFile(`pilotage-veau-${todayISO()}.json`,new Blob([JSON.stringify(o,null,1)],{type:'application/json'}))}
